private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Check if the node has a left child
    if (node.left == null) {
        return node;
    }

    // Get the left child
    TreeNode<T> left = node.left;

    // Set the node's left child to the left child's right child
    node.left = left.right;

    // Set the left child's right child to the node
    left.right = node;

    // Return the new parent of the node
    return left;
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    File dirFile = new File(dir);
    if (!dirFile.exists() || !dirFile.isDirectory()) {
        throw new IllegalArgumentException("Invalid directory: " + dir);
    }

    File[] jarFiles = dirFile.listFiles(new FilenameFilter() {
        @Override
        public boolean accept(File dir, String name) {
            return name.endsWith(".jar");
        }
    });

    for (File jarFile : jarFiles) {
        try {
            cpV.add(jarFile.toURI().toURL());
        } catch (MalformedURLException e) {
            throw new RuntimeException("Error adding jar file to classpath: " + jarFile, e);
        }
    }
}

