public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Check for null input
    if (str == null) {
        throw new IllegalArgumentException("str cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("session cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("lb cannot be null");
    }

    // Write the length of the string
    int strLen = str.length();
    lb.writeInt(strLen);

    // Write the bytes of the string
    for (int i = 0; i < strLen; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.writeByte((byte) c);
        } else if (c < 0x800) {
            lb.writeByte((byte) (0xc0 | (c >> 6)));
            lb.writeByte((byte) (0x80 | (c & 0x3f)));
        } else if (c < 0xd800 || c >= 0xe000) {
            lb.writeByte((byte) (0xe0 | (c >> 12)));
            lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3f)));
            lb.writeByte((byte) (0x80 | (c & 0x3f)));
        } else {
            // Surrogate pair
            int codePoint = c;
            i++;
            if (i < strLen) {
                char d = str.charAt(i);
                if (d >= 0xdc00 && d < 0xe000) {
                    codePoint = (((codePoint - 0xd800) << 10) | (d - 0xdc00)) + 0x10000;
                } else {
                    // Invalid surrogate pair
                    throw new IllegalArgumentException("Invalid surrogate pair at index " + i);
                }
            } else {
                // Invalid surrogate pair
                throw new IllegalArgumentException("Invalid surrogate pair at index " + i);
            }
            lb.writeByte((byte) (0xf0 | (codePoint >> 18)));
            lb.writeByte((byte) (0x80 | ((codePoint >> 12) & 0x3f)));
            lb.writeByte((byte) (0x80 | ((codePoint >> 6) & 0x3f)));
            lb.writeByte((byte) (0x80 | (codePoint & 0x3f)));
        }
    }

    return lb;
}

