public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("Desired capacity must be non-negative");
    }

    // Check if the desired capacity is already prime
    if (isPrime(desiredCapacity)) {
        return desiredCapacity;
    }

    // Find the next prime number that is greater than or equal to the desired capacity
    int prime = desiredCapacity;
    while (!isPrime(prime)) {
        prime++;
    }

    // Return the prime number that is within 11% of the desired capacity
    if (prime >= 1000) {
        return (int) (prime * 0.91);
    } else {
        return (int) (prime * 1.1);
    }
}

