public static String deleteAny(String inString, String charsToDelete) {
    // Check if the input string is null or empty
    if (inString == null || inString.isEmpty()) {
        return inString;
    }

    // Check if the characters to delete are null or empty
    if (charsToDelete == null || charsToDelete.isEmpty()) {
        return inString;
    }

    // Create a new string builder to build the result
    StringBuilder result = new StringBuilder();

    // Iterate over the characters in the input string
    for (int i = 0; i < inString.length(); i++) {
        // Check if the current character is in the set of characters to delete
        if (!charsToDelete.contains(inString.charAt(i))) {
            // If not, add it to the result string builder
            result.append(inString.charAt(i));
        }
    }

    // Return the resulting string
    return result.toString();
}

public final MatchResult match(CharSequence uri) {
    // Step 1: Check if the URI is null or empty
    if (uri == null || uri.length() == 0) {
        return null;
    }

    // Step 2: Initialize the match result
    MatchResult result = new MatchResult();

    // Step 3: Iterate over the template and URI characters
    for (int i = 0; i < template.length(); i++) {
        char c = template.charAt(i);
        if (c == '*') {
            // Step 4: If the current character is a wildcard, check if the next character in the URI is also a wildcard
            if (i + 1 < uri.length() && uri.charAt(i + 1) == '*') {
                // Step 5: If the next character is also a wildcard, skip it and continue iterating
                i++;
                continue;
            }

            // Step 6: If the next character is not a wildcard, check if it matches the current character in the template
            if (i + 1 < uri.length() && uri.charAt(i + 1) == c) {
                // Step 7: If the next character matches, skip it and continue iterating
                i++;
                continue;
            }

            // Step 8: If the next character does not match, return null
            return null;
        }

        // Step 9: If the current character is not a wildcard, check if it matches the current character in the URI
        if (i < uri.length() && uri.charAt(i) == c) {
            // Step 10: If the character matches, continue iterating
            continue;
        }

        // Step 11: If the character does not match, return null
        return null;
    }

    // Step 12: If the template is fully matched, return the match result
    return result;
}

