public boolean isCompatible(DataTable dataset) {
    // Check if the bucket is same
    if (this.bucket == dataset.bucket) {
        return true;
    }

    // Check if the bucket is null
    if (this.bucket == null || dataset.bucket == null) {
        return false;
    }

    // Check if the bucket names are the same
    if (this.bucket.getName().equals(dataset.bucket.getName())) {
        return true;
    }

    // Check if the bucket locations are the same
    if (this.bucket.getLocation().equals(dataset.bucket.getLocation())) {
        return true;
    }

    // Check if the bucket types are the same
    if (this.bucket.getType().equals(dataset.bucket.getType())) {
        return true;
    }

    // Check if the bucket capacities are the same
    if (this.bucket.getCapacity().equals(dataset.bucket.getCapacity())) {
        return true;
    }

    // Check if the bucket volumes are the same
    if (this.bucket.getVolume().equals(dataset.bucket.getVolume())) {
        return true;
    }

    // Check if the bucket weights are the same
    if (this.bucket.getWeight().equals(dataset.bucket.getWeight())) {
        return true;
    }

    // Check if the bucket dimensions are the same
    if (this.bucket.getDimensions().equals(dataset.bucket.getDimensions())) {
        return true;
    }

    // Check if the bucket is the same
    return false;
}

