    // Get the next vertex to visit
    V nextVertex = vertices.remove(0);

    // Check if the next vertex has already been visited
    if (visited.contains(nextVertex)) {
        // If the next vertex has already been visited, return the next vertex
        return nextVertex;
    }

    // Mark the next vertex as visited
    visited.add(nextVertex);

    // Return the next vertex
    return nextVertex;
}

