public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Check if the nameStart is a valid index in the buffer
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid nameStart index");
    }

    // Get the first letter of the name
    char firstLetter = buf.charAt(nameStart);

    // Check if the first letter is a vowel
    if (firstLetter == 'a' || firstLetter == 'e' || firstLetter == 'i' || firstLetter == 'o' || firstLetter == 'u') {
        // Append the first letter and a dot
        buf.append(firstLetter).append('.');
    } else {
        // Get the second letter of the name
        char secondLetter = buf.charAt(nameStart + 1);

        // Check if the second letter is a vowel
        if (secondLetter == 'a' || secondLetter == 'e' || secondLetter == 'i' || secondLetter == 'o' || secondLetter == 'u') {
            // Append the first two letters and a dot
            buf.append(firstLetter).append(secondLetter).append('.');
        } else {
            // Append the first letter and a dot
            buf.append(firstLetter).append('.');
        }
    }
}

