public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }

    int strLength = str.length();
    int substringLength = substring.length();

    if (index < 0 || index + substringLength > strLength) {
        return false;
    }

    for (int i = 0; i < substringLength; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

protected void append(LoggingEvent event) {
    // Check if there are any connected clients
    if (connectedClients.isEmpty()) {
        return;
    }

    // Create a new message to be sent to each client
    String message = event.getMessage();

    // Iterate over each connected client and send the message
    for (Client client : connectedClients) {
        try {
            client.sendMessage(message);
        } catch (IOException e) {
            // If an exception is thrown while sending the message, remove the client from the list of connected clients
            connectedClients.remove(client);
        }
    }
}

